// Writes supabase/functions/_shared/stores.generated.ts from every
// tenants/<slug>/tenant.json, so the Edge Functions brand and address each
// store's emails from the same facts as its website. The functions are
// deployed on their own (Deno), so they cannot read tenant.json at run time.
//
// Run after changing any tenant.json, then commit the generated file:
//   node scripts/build-function-stores.mjs
// src/__tests__/functionStores.unit.test.js fails while the file is stale.
import { readdirSync, writeFileSync, existsSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { loadTenant } from '../tenants/loadTenant.mjs'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
export const OUT = path.join(ROOT, 'supabase/functions/_shared/stores.generated.ts')

export function storeSlugs() {
  return readdirSync(path.join(ROOT, 'tenants'), { withFileTypes: true })
    .filter(d => d.isDirectory() && existsSync(path.join(ROOT, 'tenants', d.name, 'tenant.json')))
    .map(d => d.name)
    .sort()
}

/** The email-facing facts of one store, as the functions see them. */
export function functionStore(t) {
  const c = t.contact
  return {
    slug: t.slug,
    name: t.name,
    shortName: t.shortName,
    siteUrl: t.domain.siteUrl,
    // Storage object path; the functions prefix SUPABASE_URL at run time.
    logoPath: t.images.logoWide,
    address: [c.street, c.suburb, c.city, c.postalCode].filter(Boolean).join(', '),
    phone: c.phoneDisplay,
    hours: t.mail.footerHours,
    instagram: t.social?.instagram ?? null,
    facebook: t.social?.facebook ?? null,
    gold: t.theme.colors.gold,
    minimumAge: t.minimumAge,
    bankDetails: t.bank?.details ?? null,
    mail: {
      fromDomain: t.mail.fromDomain,
      fromDomainEnv: t.mail.fromDomainEnv ?? null,
      resendKeyEnv: t.mail.resendKeyEnv,
      bankDetailsEnv: t.mail.bankDetailsEnv ?? null,
    },
  }
}

export function generateStoresModule() {
  const stores = Object.fromEntries(storeSlugs().map(slug => [slug, functionStore(loadTenant(slug))]))
  return [
    '// GENERATED by scripts/build-function-stores.mjs from tenants/*/tenant.json.',
    '// Do not edit by hand: change tenant.json and re-run the script.',
    '',
    `export const STORES = ${JSON.stringify(stores, null, 2)} as const`,
    '',
  ].join('\n')
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFileSync(OUT, generateStoresModule())
  console.log(`wrote ${path.relative(ROOT, OUT)} (${storeSlugs().join(', ')})`)
}
